// electron/utils/actionItemExtractor.ts
//
// Deterministic safety net for meeting action items.
//
// The LLM summary repeatedly drops tasks that have an owner but no deadline
// ("Priya will send the contract"). Prompt tweaks alone have not been reliable,
// so after the LLM runs we scan the transcript ourselves for owner commitments
// and append any the LLM missed. This does NOT require a date.

export interface ExtractorSegment {
    speaker: string;
    text: string;
}

// Capitalized words that start sentences but are not people.
const NON_OWNER_WORDS = new Set([
    'i', 'we', 'you', 'he', 'she', 'they', 'it', 'that', 'this', 'there', 'these', 'those',
    'what', 'which', 'who', 'when', 'where', 'why', 'how', 'if', 'then', 'so', 'and', 'but',
    'or', 'also', 'maybe', 'perhaps', 'hopefully', 'everyone', 'everybody', 'someone',
    'somebody', 'nobody', 'anyone', 'anybody', 'nothing', 'something', 'everything', 'one',
    'the', 'a', 'an', 'our', 'your', 'my', 'their', 'his', 'her', 'its', 'today', 'tomorrow',
    'yes', 'no', 'okay', 'ok', 'well', 'now', 'next', 'here', 'all', 'both', 'each', 'nothing',
    'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday',
    'january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september',
    'october', 'november', 'december',
]);

// First words after "will" that signal a prediction/filler, not a task.
const NON_TASK_VERBS = new Set([
    'be', 'probably', 'never', 'always', 'not', 'say', 'admit', 'guess', 'bet', 'think',
    'mean', 'assume', 'see', 'just', 'likely', 'definitely', 'love', 'like', 'hate', 'get', 'go',
    'come', 'have', 'need', 'want', 'know', 'tell', 'happen', 'work', 'take', 'make',
]);

const DATE_HINT = /\b(by|before|until|on|next|this|tomorrow|tonight|today|eod|eow|end of|monday|tuesday|wednesday|thursday|friday|saturday|sunday|week|month|quarter|q[1-4]|\d{1,2}(st|nd|rd|th)?|january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\b/i;

// "Priya will send…", "Priya'll send…", "Priya is going to send…", "Priya is gonna send…"
const THIRD_PERSON = /(?:^|[\s,;:—-])([A-Z][a-z]+(?:\s[A-Z][a-z]+)?)(?:\s+will|'ll|\s+is\s+going\s+to|\s+is\s+gonna|\s+is\s+to|\s+needs\s+to|\s+has\s+to)\s+([a-z][^.?!;]{2,120})/g;
// "Priya, can you send…", "Priya, could you please send…"
const DIRECT_ASK = /(?:^|[\s,;:—-])([A-Z][a-z]+),\s+(?:can|could|would)\s+you\s+(?:please\s+)?([a-z][^.?!;]{2,120})/g;
// "I'll send…", "I will send…", "I'm going to send…" — only from the local user (speaker 'user')
const FIRST_PERSON = /(?:^|[\s,;:—-])I(?:'ll|\s+will|'m\s+going\s+to|\s+am\s+going\s+to|'m\s+gonna)\s+([a-z][^.?!;]{2,120})/g;

function cleanTask(task: string): string | null {
    let t = task.trim().replace(/\s+/g, ' ').replace(/[,\s]+(right|okay|ok|yeah)\??$/i, '');
    const firstWord = t.split(' ')[0].toLowerCase();
    if (NON_TASK_VERBS.has(firstWord)) return null;
    if (t.split(' ').length < 2) return null; // "Priya will do" is too vague
    t = t.charAt(0).toUpperCase() + t.slice(1);
    return t;
}

function format(owner: string, task: string): string {
    return DATE_HINT.test(task) ? `${owner}: ${task}` : `${owner}: ${task} (no date given)`;
}

function contentWords(s: string): string[] {
    return s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length >= 4);
}

/** True if an existing item already covers this owner + task. */
function isCovered(owner: string, task: string, existing: string[]): boolean {
    const ownerKey = owner.toLowerCase();
    const ownerAliases = ownerKey === 'me' ? ['me', 'i ', 'you', 'my '] : [ownerKey.split(' ')[0]];
    const words = contentWords(task);
    return existing.some(item => {
        const lower = item.toLowerCase();
        if (!ownerAliases.some(a => lower.includes(a))) return false;
        if (words.length === 0) return true;
        const hits = words.filter(w => lower.includes(w)).length;
        return hits / words.length >= 0.5;
    });
}

/** Find owner commitments in the transcript, with or without a deadline. */
export function extractCommitments(segments: ExtractorSegment[]): Array<{ owner: string; task: string }> {
    const found: Array<{ owner: string; task: string }> = [];
    for (const seg of segments) {
        const text = (seg.text || '').trim();
        if (!text || seg.speaker === 'assistant') continue;

        for (const re of [THIRD_PERSON, DIRECT_ASK]) {
            re.lastIndex = 0;
            let m: RegExpExecArray | null;
            while ((m = re.exec(text)) !== null) {
                const owner = m[1];
                if (owner.split(' ').some(w => NON_OWNER_WORDS.has(w.toLowerCase()))) continue;
                const task = cleanTask(m[2]);
                if (task) found.push({ owner, task });
            }
        }

        if (seg.speaker === 'user') {
            FIRST_PERSON.lastIndex = 0;
            let m: RegExpExecArray | null;
            while ((m = FIRST_PERSON.exec(text)) !== null) {
                const task = cleanTask(m[1]);
                if (task) found.push({ owner: 'Me', task });
            }
        }
    }
    return found;
}

/**
 * Return `existing` plus any transcript commitments the LLM missed.
 * Never removes or rewrites what the LLM produced.
 */
export function mergeMissingActionItems(existing: string[], segments: ExtractorSegment[], maxAdded = 15): string[] {
    const result = [...existing];
    let added = 0;
    for (const { owner, task } of extractCommitments(segments)) {
        if (added >= maxAdded) break;
        if (isCovered(owner, task, result)) continue;
        result.push(format(owner, task));
        added++;
    }
    return result;
}

